 assert len(groups)==7 and all(len(v)==5 for v in groups.values())
 return {mode:{'ns':statistics.median(v['ns'] for v in vs),'min_ns':min(v['ns'] for v in vs),'max_ns':max(v['ns'] for v in vs),'bytes':statistics.median(v['bytes'] for v in vs),'allocs':statistics.median(v['allocs'] for v in vs)} for mode,vs in groups.items()}
