 overhead=[{'mode':mode,'before':before[mode],'after':after[mode],'bytes_saved':before[mode]['bytes']-after[mode]['bytes'],'allocations_saved':before[mode]['allocs']-after[mode]['allocs'],'time_change_percent':(after[mode]['ns']/before[mode]['ns']-1)*100} for mode in before]
