 fig.suptitle('Seeded arrivals: useful work under overload',x=.025,ha='left',fontsize=17,y=.98);fig.text(.025,.025,'1,800 total requests/sec; 10 ms SQL delay; four SQL connections per service. Same per-seed traffic plan across policies.\nMedians of three paired seeds, with min/max ranges, not confidence intervals. Rate caps are per service; proxy adds a hop.\nFixed reservation sweep is predeclared. Read both priorities, refusals, errors and service-level results in the table.',color='#a9bfb0');fig.tight_layout(rect=(0,.11,1,.95));fig.savefig(ROOT/'public/images/hardening-seeded.png',dpi=150);plt.close(fig)
 sweep=['fixed-unreserved','middleware-fixed','fixed-reserved-2','fixed-reserved-3','fixed-service-reservations'];fig,axes=plt.subplots(1,3,figsize=(17,8))
 for i,role in enumerate(['orders','catalog','inventory']):
  for offset,tier,color in [(-.18,'critical','#76d9bc'),(.18,'background','#829d8e')]:axes[i].barh([j+offset for j in range(len(sweep))],[row(c,'background-flood',role,tier)['timely_rps'] for c in sweep],height=.34,color=color,label=tier)
  axes[i].invert_yaxis();axes[i].set_yticks(range(len(sweep)),['Reserve 0','Reserve 1','Reserve 2','Reserve 3','Orders 2 / catalog 1 / inventory 1'] if i==0 else []);axes[i].set_title(role.capitalize());axes[i].set_xlabel('Within 100 ms / sec');axes[i].grid(axis='x',alpha=.12);axes[i].set_axisbelow(True);axes[i].spines[['top','right']].set_visible(False)
 axes[2].legend(facecolor='#101b16',labelcolor='#dae8df');fig.suptitle('Reservations change who gets capacity',x=.025,ha='left',fontsize=17,y=.97);fig.text(.025,.025,'Fixed middleware; ceiling 4; background-flood phase; three paired seeds. Separate critical/background median bars.\nReservations are not extra capacity. A critical gain can reduce background progress or leave slots unused.\nThe 2/1/1 configuration is a predeclared example, not an automatically selected optimum.',color='#a9bfb0');fig.tight_layout(rect=(0,.16,1,.92));fig.savefig(ROOT/'public/images/hardening-reservations.png',dpi=150);plt.close(fig)
