 axes[1].legend(facecolor='#101b16',labelcolor='#dae8df');fig.suptitle('Remove redundant trace allocation without removing diagnostics',x=.025,ha='left',fontsize=16,y=.97);fig.text(.025,.025,'Five sequential successful no-op repeats per mode; medians on the same host/toolchain. No SQL, network or waiting contention.\nAllocated bytes/op fall by 720 and allocations/op by 3 in every tested Gatewise middleware mode with signals disabled. Public diagnostic views remain detached.\nThese timings are not a production capacity claim or a comparison to another project\'s reported overhead.',color='#a9bfb0');fig.tight_layout(rect=(0,.19,1,.92));fig.savefig(ROOT/'public/images/hardening-overhead.png',dpi=150);plt.close(fig)
